  // ── Egen butik (distribution) ──
  'dist.locked': ['Forska fram Digital butik (Affärer, från 2003, efter Serverrum) för att bygga en egen butik och launcher för pc-spel.', 'Research Digital Storefront (Business, from 2003, after Server Room) to build your own PC store and launcher.'],
  'dist.help': ['Butiken säljer pc-spel. De pc-spelare som använder den köper dina pc-spel här, så du behåller de {pct} % som andra butiker tar. Koncernens spel (dotterbolag och förlagets spel) säljs alltid här.', 'The store sells PC games. PC players who use it buy your PC games here, so you keep the {pct}% other stores take. The group\'s games (subsidiaries and your label) are always sold here.'],
  'dist.users': ['Användare', 'Users'],
  'dist.usersK': ['{pct} % av pc-spelarna', '{pct}% of PC players'],
  'dist.usersTip': ['Användarbasen växer mot {pct} % av pc-spelarna: koncernens pc-spel, dina fans, andra förlags spel, förtroendet, upptäckbarheten och marknadsföringen avgör.', 'The user base grows toward {pct}% of PC players, driven by the group\'s PC games, your fans, other publishers\' games, trust, discoverability and marketing.'],
  'dist.toward': ['på väg mot {pct} %', 'heading for {pct}%'],
  'dist.trust': ['Förtroende', 'Trust'],
  'dist.trustTip': ['Kundernas och förlagens förtroende. Låg avgift, bra support och bra spel höjer det; exklusiva spel, driftstopp, höjda avgifter och svaga spel sänker det.', 'How much customers and publishers trust the store. Low fees, good support and good games raise it; exclusives, outages, fee hikes and weak games lower it.'],
  'dist.disc': ['Upptäckbarhet', 'Discoverability'],
  'dist.discTip': ['Hur lätt kunderna hittar rätt spel. Lätt i en sluten butik, svårare ju fler förlag som säljer i en öppen. Hög upptäckbarhet lockar användare och låter dina spel synas.', 'How easily customers find the right game. Easy in a closed store, harder the more publishers sell in an open one. High discoverability draws users and lets your games stand out.'],
  'dist.devs': ['Andra förlag', 'Other publishers'],
  'dist.devsK': ['av förlagens pc-spel säljs här', 'of publishers\' PC games sold here'],
  'dist.devsTip': ['Andelen av andra förlags pc-spel som säljs i butiken. Lägre avgift och högre förtroende lockar fler; de kommer och går långsamt.', 'The share of other publishers\' PC games sold in the store. Lower fees and higher trust draw more; they come and go slowly.'],
  'dist.policy': ['Strategi', 'Strategy'],
  'dist.closed': ['Sluten butik', 'Closed store'],
  'dist.closedD': ['Bara koncernens spel. Butiken är ditt skyltfönster: dina pc-spel syns överallt och säljer mer, kunderna kommer för dina spel och driften är billigare. Lönar sig med många bra pc-spel.', 'Only the group\'s games. The store is your shop window: your PC games are everywhere and sell more, customers come for your games and running it is cheaper. Pays off with many good PC games.'],
  'dist.open': ['Öppen butik', 'Open store'],
  'dist.openD': ['Alla förlag får sälja mot din avgift. Fler spel lockar fler kunder och avgifterna blir en egen inkomst, men dina spel syns mindre bland alla andra och förlagen kräver relationer och granskning.', 'Every publisher may sell for your fee. More games draw more customers and the fees become an income of their own, but your games stand out less among the rest and publishers need relations and review.'],
  'dist.featNow': ['Dina nya pc-spel: +{pct} % försäljning', 'Your new PC games: +{pct}% sales'],
