  'tut.welcome.h': ['Välkommen till din studio', 'Welcome to your studio'],
  'tut.welcome.b': ['Du börjar i ett garage. Gör spel, tjäna pengar, forska och bygg upp en spelstudio som blir en dynasti. Spelet går i din takt: pausa när du vill tänka.', 'You start in a garage. Make games, earn money, research and build a studio into a dynasty. The game runs at your pace: pause whenever you want to think.'],
  'tut.goals.h': ['Dina mål', 'Your goals'],
  'tut.goals.b': ['Rutan <b>Mål</b> visar vad som är nästa steg. Varje klart mål ger pengar, fans eller forskningspoäng. Öppna den och se vad du kan klara härnäst.', 'The <b>Goals</b> tile shows what to do next. Every finished goal gives money, fans or research points. Open it and see what you can do next.'],
  'tut.create.h': ['Gör ditt första spel', 'Make your first game'],
  'tut.create.b': ['Klicka på <b>Nytt spel</b> i menyn nedan. Välj tema, genre och plattform.', 'Click <b>New game</b> in the bar below. Pick a topic, genre and platform.'],
  'tut.dev.h': ['Utveckling pågår', 'Development under way'],
  'tut.dev.b': ['Blå siffror är <b>design</b>, gröna är <b>teknik</b> och röda är <b>buggar</b>. När en ny fas börjar väljer du nytt fokus.', 'Blue numbers are <b>design</b>, green are <b>tech</b> and red are <b>bugs</b>. When a new phase starts you pick a new focus.'],
  'tut.research.h': ['Dags att forska', 'Time to research'],
  'tut.research.b': ['Öppna <b>Forska</b> och starta något. Nya teman, genrer och funktioner låses upp.', 'Open <b>Research</b> and start something. New topics, genres and features unlock.'],
  'tut.again.h': ['Nästa spel!', 'Next game!'],
  'tut.again.b': ['Skapa ett nytt spel medan forskningen pågår. Lär dig vilka kombinationer som funkar.', 'Make another game while research runs. Learn which combinations work.'],
  'tut.team.h': ['Anställ hjälp', 'Hire some help'],
  'tut.team.b': ['Fler händer ger högre kvalitet. Öppna <b>Personal</b> och anställ en kandidat.', 'More hands mean better quality. Open <b>Staff</b> and hire a candidate.'],
  'tut.studio.h': ['Ut ur garaget', 'Out of the garage'],
