  'hw.drvHelp': ['Höjer spelstödet en poäng var fjärde vecka, upp till 90.', 'Raises game support one point every four weeks, up to 90.'],
  'hw.drvDone': ['Spelstödet är redan så högt som ett team kan få det.', 'Game support is already as high as a team can make it.'],
  'hw.offerT': ['Erbjudande från {partner}', 'An offer from {partner}'],
  'hw.offerText': ['{partner} vill ha ensamrätt på den här produkttypen i {n} år: 5 % lägre pris och dubbel förtur vid komponentbrist. Under tiden kan nya produkter av typen inte tillverkas hos någon annan, och du kan inte byta partner för dem. Svarar du inte inom {w} veckor går erbjudandet ut.', '{partner} wants exclusive rights to this product type for {n} years: 5% lower prices and double priority in a component shortage. Meanwhile new products of the type cannot be made anywhere else, and you cannot switch their partner. If you do not answer within {w} weeks, the offer lapses.'],
  'hw.offerYes': ['Skriv på', 'Sign'],
  'hw.offerNo': ['Tacka nej', 'Decline'],
  'hw.exclTag': ['Ensamrätt: {type} till {y}', 'Exclusive: {type} until {y}'],
  'hw.exclLock': ['Låst: {partner} har ensamrätt på typen till {y}.', 'Locked: {partner} has exclusive rights to the type until {y}.'],
  'hw.patentT': ['Patentstämning', 'Patent lawsuit'],
  'hw.patentText': ['Ett patentbolag hävdar att din egen processordesign bryter mot deras patent. Gör upp utanför rätten för en procent av årets hårdvaruintäkt, eller gå till rättegång: hälften av gångerna vinner du, annars kostar domen fyra procent. Väljer du inte inom {w} veckor gör juristerna upp åt dig.', 'A patent company claims your own processor design infringes their patent. Settle out of court for one percent of the yearly hardware revenue, or go to trial: half the time you win, otherwise the verdict costs four percent. If you do not choose within {w} weeks your lawyers settle.'],
  'hw.patentSettle': ['Gör upp ({v})', 'Settle ({v})'],
  'hw.patentTrial': ['Gå till rättegång', 'Go to trial'],
  'hw.patentTrialTip': ['Hälften av gångerna kostar det inget, annars {v}.', 'Half the time it costs nothing, otherwise {v}.'],
  'hw.leaked': ['Designen har läckt. Intresset växer, men konkurrenterna hinner förbereda ett svar.', 'The design has leaked. Interest is growing, but rivals have time to prepare a response.'],
  'hw.leakReady': ['Designen läckte: produkten får ett förhandsintresse, men konkurrenterna svarar de första veckorna.', 'The design leaked: the product gets early interest, but rivals respond in the first weeks.'],
  'hw.leakTag': ['Konkurrenterna svarar på läckan', 'Rivals answer the leak'],
  'hw.s.digital': ['Digitalt via butiken', 'Digital via your store'],
  'hw.s.digitalTip': ['Så stor del av spelen på plattformen säljs digitalt i din butik. Där behåller du avgiften på dina spel och tar {pct} % av andra förlags försäljning i stället för licensavgiften.', 'This share of the games on the platform sells digitally in your store. There you keep the fee on your games and take {pct}% of other publishers\' sales instead of the license fee.'],
  'hw.s.storeW': ['Butikens del', 'Store share'],
  'hw.s.storeWTip': ['Butikens del av andra förlags digitala försäljning på plattformen. Den bokförs i butiken.', 'The store\'s share of other publishers\' digital sales on the platform. It is booked in the store.'],
  'hw.storeHint': ['Med en egen digital butik säljs en växande del av spelen på plattformen digitalt där.', 'With your own digital store, a growing share of the games on the platform sells digitally there.'],
  'hw.exT': ['Exklusiva spel från andra förlag', 'Exclusive games from other publishers'],
  'hw.exHelp': ['Betala ett förlag för att släppa sitt nästa spel bara här (ett köp per halvår). Spelet säljer efter plattformens storlek, du får licensavgiften på det, det räknas bland plattformens spel och ett hit säljer fler enheter. Läggs plattformen ned före släppet får du tillbaka hälften.', 'Pay a publisher to release its next game only here (one purchase every half year). The game sells by the platform\'s size, you get the license fee on it, it counts among the platform\'s games and a hit sells more units. If the platform is discontinued before the release, you get half back.'],
  'hw.exIn': ['om {n} v', 'in {n} wk'],
  'hw.exBuy': ['Köp ({v})', 'Buy ({v})'],
  'hw.exBought': ['Köpt exklusivt', 'Bought exclusive'],
  'hw.exSmall': ['Förlagen vill ha en plattform med storlek minst {n}.', 'Publishers want a platform of size {n} or more.'],
  'hw.exWait': ['Förlagen tar ett exklusivt spel i taget: nästa köp går om {n} veckor.', 'Publishers take one exclusive at a time: the next purchase opens in {n} weeks.'],
  'hw.exTip': ['Nästa spel släpps bara på {name}.', 'The next game is released only on {name}.'],
  'hw.end': ['Lägg ned', 'Discontinue'],
  'hw.endYes': ['Lägg ned produkten', 'Discontinue the product'],
  'hw.endWarn': ['Order som inte tillverkats avbokas (halva pengarna tillbaka) och lagret reas ut för {pct} % av priset.', 'Orders not yet made are cancelled (half the money back) and the stock is cleared at {pct}% of the price.'],
  'hw.batch': ['En felaktig serie på {n} enheter har upptäckts. Återkalla den, eller låt bli och hoppas att ingen märker något.', 'A faulty batch of {n} units has been found. Recall it, or let it be and hope nobody notices.'],
